"use client";

import { useEffect, useMemo, useState } from "react";
import {
  Activity,
  CalendarDays,
  Heart,
  HeartPulse,
  LayoutDashboard,
  LoaderCircle,
  Moon,
  RefreshCw,
  TrendingUp,
} from "lucide-react";
import {
  Area,
  AreaChart,
  CartesianGrid,
  ReferenceArea,
  ReferenceLine,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";

type MetricKey = "hrv" | "sleep" | "restingHeartRate" | "stress";
type RecoveryMetricKey = MetricKey | "sleepScore" | "bodyBattery";
type DateRange = 7 | 30;
type MetricPoint = { date: string; value: number };
type MetricData = {
  label: string;
  unit: string;
  points: MetricPoint[];
  latest: MetricPoint | null;
  baseline7: number | null;
  baseline28: number | null;
  usualRange28: [number, number] | null;
  rangeLabel: string;
  garminStatus: string | null;
  status: "unavailable" | "insufficient_history" | "within_usual" | "below_usual" | "above_usual";
  availableDays: number;
  unavailableReason: string | null;
};
type TrainingBriefing = {
  approach: string;
  explanation: string;
  dataSufficiency: string;
  evidence: Array<{ metric: string; direction: "below" | "above"; isCaution: boolean; usualRange: [number, number] | null; unit: string }>;
  medicalDisclaimer: string;
};
type DashboardData = {
  period: { days: number; startDate: string; endDate: string };
  metrics: Record<RecoveryMetricKey, MetricData>;
  coverageDays: number;
  trainingBriefing: TrainingBriefing;
};

const metricOptions: MetricKey[] = ["hrv", "restingHeartRate", "sleep", "stress"];
const timelineMetricOptions: RecoveryMetricKey[] = ["hrv", "sleepScore", "sleep", "restingHeartRate", "bodyBattery", "stress"];

const metricDisplay: Record<RecoveryMetricKey, { label: string; color: string }> = {
  hrv: { label: "HRV", color: "#13765d" },
  restingHeartRate: { label: "Resting heart rate", color: "#c66c4b" },
  sleep: { label: "Sleep duration", color: "#527b9d" },
  stress: { label: "Stress", color: "#b18432" },
  bodyBattery: { label: "Body Battery", color: "#13765d" },
  sleepScore: { label: "Sleep score", color: "#527b9d" },
};

/** Fetch uncached health data through the same-origin server route. */
async function fetchDashboardData(days: DateRange): Promise<DashboardData> {
  const response = await fetch("/api/health", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ days }),
    cache: "no-store",
  });
  const payload = await response.json() as DashboardData | { error?: string };
  if (!response.ok || !("metrics" in payload)) {
    throw new Error("Garmin health data could not be loaded.");
  }
  return payload;
}

/** Format an ISO calendar date without timezone drift. */
function formatDate(value: string): string {
  return new Date(`${value}T12:00:00`).toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

/** Present a metric using the unit returned by the Garmin adapter. */
function formatValue(key: MetricKey, value: number, unit: string): string {
  if (unit === "hours") {
    const totalMinutes = Math.round(value * 60);
    return `${Math.floor(totalMinutes / 60)}h ${totalMinutes % 60}m`;
  }
  return `${Number.isInteger(value) ? value : value.toFixed(1)} ${unit}`.trim();
}

/** Format a day-strip value compactly while its row supplies the unit. */
function formatTimelineValue(metricKey: RecoveryMetricKey, value: number): string {
  if (metricKey === "sleep") {
    return `${value.toFixed(1)}h`;
  }
  return Number.isInteger(value) ? String(value) : value.toFixed(1);
}

/** Classify each reading only against its Garmin or personal baseline. */
function getTimelineStatus(metric: MetricData | undefined, value: number): "within" | "outside" | "unavailable" {
  if (!metric?.usualRange28) {
    return "unavailable";
  }
  return value < metric.usualRange28[0] || value > metric.usualRange28[1] ? "outside" : "within";
}

/** Render the personal Garmin dashboard using only values returned by the API. */
export default function HealthDashboard() {
  const [dateRange, setDateRange] = useState<DateRange>(30);
  const [selectedMetric, setSelectedMetric] = useState<MetricKey>("hrv");
  const [dashboardData, setDashboardData] = useState<DashboardData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);

  useEffect(() => {
    let isCurrent = true;
    setIsLoading(true);
    setLoadError(null);
    fetchDashboardData(30)
      .then((data) => {
        if (isCurrent) {
          setDashboardData(data);
        }
      })
      .catch(() => {
        if (isCurrent) {
          setLoadError("Garmin data could not be loaded. Check your Personal API key and connection.");
        }
      })
      .finally(() => {
        if (isCurrent) {
          setIsLoading(false);
        }
      });
    return () => {
      isCurrent = false;
    };
  }, []);

  async function refreshDashboard(): Promise<void> {
    setIsLoading(true);
    setLoadError(null);
    try {
      setDashboardData(await fetchDashboardData(30));
    } catch {
      setLoadError("Garmin data could not be loaded. Check your Personal API key and connection.");
    } finally {
      setIsLoading(false);
    }
  }

  const currentData = dashboardData;
  const selectedSeries = metricDisplay[selectedMetric];
  const selectedMetricData = currentData?.metrics[selectedMetric];
  const chartData = useMemo(
    () => selectedMetricData?.points.slice(-dateRange).map((point) => ({ ...point, date: formatDate(point.date) })) ?? [],
    [selectedMetricData, dateRange],
  );
  const timelineDays = useMemo(() => {
    const days = new Set<string>();
    for (const metricKey of timelineMetricOptions) {
      for (const point of currentData?.metrics[metricKey].points ?? []) {
        days.add(point.date);
      }
    }
    return [...days].sort().slice(-7);
  }, [currentData]);
  const chartDomain = useMemo<[number, number] | ["auto", "auto"]>(() => {
    const values = [
      ...chartData.map((point) => point.value),
      ...(selectedMetricData?.usualRange28 ?? []),
      ...(selectedMetricData?.baseline28 === null || selectedMetricData?.baseline28 === undefined ? [] : [selectedMetricData.baseline28]),
    ];
    if (!values.length) {
      return ["auto", "auto"];
    }
    const minimum = Math.min(...values);
    const maximum = Math.max(...values);
    const padding = Math.max((maximum - minimum) * 0.12, Math.abs(maximum) * 0.03, 0.5);
    return [minimum - padding, maximum + padding];
  }, [chartData, selectedMetricData]);
  const personalMedian = selectedMetric === "hrv" ? null : selectedMetricData?.baseline28 ?? null;
  const trainingBriefing = currentData?.trainingBriefing;
  const availableBaselineCount = currentData
    ? Object.values(currentData.metrics).filter((metric) => metric.usualRange28 !== null).length
    : 0;

  return (
    <div className="app-shell">
      <aside className="sidebar" aria-label="Main navigation">
        <a className="brand" href="#overview" aria-label="Garmin Health Signals overview">
          <span className="brand-mark"><Activity size={21} strokeWidth={2.4} /></span>
          <span className="brand-copy"><strong>GARMIN</strong><small>HEALTH SIGNALS</small></span>
        </a>
        <div className="nav-caption">WORKSPACE</div>
        <nav className="side-nav">
          <a className="nav-item is-active" href="#overview" aria-current="page"><LayoutDashboard size={17} /><span>Overview</span></a>
          <a className="nav-item" href="#health-signals"><HeartPulse size={17} /><span>Health signals</span></a>
          <a className="nav-item" href="#patterns"><TrendingUp size={17} /><span>Patterns</span></a>
        </nav>
        <div className="sidebar-bottom">
          <div className="privacy-note"><span className="privacy-dot" /><span>LOCAL PERSONAL API</span></div>
        </div>
      </aside>

      <main className="main-content" id="overview">
        <header className="topbar">
          <div className="breadcrumb"><span>Personal health</span><span className="crumb-divider">/</span><strong>Overview</strong></div>
          <div className="topbar-actions">
            <span className="data-badge"><span className={currentData ? "connected-dot" : ""} />{isLoading ? "FETCHING" : currentData ? "GARMIN DATA" : "NO DATA"}</span>
            <button
              className="sync-button"
              type="button"
              onClick={() => void refreshDashboard()}
              disabled={isLoading}
              aria-busy={isLoading}
              aria-label={isLoading ? "Refreshing Garmin data" : "Refresh Garmin data"}
            >
              {isLoading ? <LoaderCircle size={15} /> : <RefreshCw size={15} />}
              <span>{isLoading ? "Loading…" : "Refresh data"}</span>
            </button>
          </div>
        </header>

        <div className="page-content">
          {loadError && <div className="state-notice sync-error" role="alert">{loadError}</div>}
          {isLoading && !currentData && <div className="state-notice loading" role="status">Loading health metrics from Garmin…</div>}
          <section className="page-heading" aria-labelledby="page-title">
            <div>
              <div className="eyebrow"><CalendarDays size={14} />{currentData ? `${formatDate(currentData.period.startDate)}–${formatDate(currentData.period.endDate)}` : "GARMIN PERSONAL DATA"}</div>
              <h1 id="page-title">Your health, in context.</h1>
              <p className="page-subtitle">Available readings compared with your recent personal baselines.</p>
            </div>
            <div className="range-select" aria-label="Selected date range"><CalendarDays size={16} /><span>Last {dateRange} days</span></div>
          </section>

          <section className="metrics-grid" id="health-signals" aria-label="Garmin health signals and personal baselines">
            <MetricCard icon={<HeartPulse size={18} />} iconClass="icon-green" metricKey="hrv" metric={currentData?.metrics.hrv} />
            <MetricCard icon={<Heart size={18} />} iconClass="icon-coral" metricKey="restingHeartRate" metric={currentData?.metrics.restingHeartRate} />
            <MetricCard icon={<Moon size={18} />} iconClass="icon-blue" metricKey="sleep" metric={currentData?.metrics.sleep} />
            <MetricCard icon={<HeartPulse size={18} />} iconClass="icon-amber" metricKey="stress" metric={currentData?.metrics.stress} />
          </section>

          <section className="briefing-panel insight-panel" aria-labelledby="briefing-heading">
            <div className="briefing-main">
              <div className="briefing-label"><HeartPulse size={15} /> TODAY&apos;S GUIDANCE</div>
              <h2 id="briefing-heading">{trainingBriefing?.approach ?? (isLoading ? "Loading your health data" : "No training suggestion")}</h2>
              <p>{trainingBriefing?.explanation ?? loadError ?? "A suggestion appears when enough recent health history is available."}</p>
              <div className="briefing-disclaimer">General guidance · Not medical advice</div>
            </div>
            <div className="briefing-evidence" aria-label="Signals supporting the training approach">
              <div className="evidence-heading">WHAT&apos;S DIFFERENT</div>
              {trainingBriefing?.evidence.length ? trainingBriefing.evidence.map((item, index) => (
                <div className="evidence-row" key={item.metric}>
                  <span className="evidence-check">{index + 1}</span>
                  <span>{item.metric}</span>
                  <strong>{item.direction === "below" ? "Below your usual range" : "Above your usual range"}</strong>
                </div>
              )) : (
                <p className="evidence-empty">{trainingBriefing?.dataSufficiency === "Limited history" ? "Not enough history to compare yet." : trainingBriefing ? "No unusual signals in these readings." : "No comparison is available yet."}</p>
              )}
            </div>
          </section>

          <div className="lower-grid">
            <section className="panel trend-panel" aria-labelledby="trend-heading">
              <div className="panel-header trend-header">
                <div><div className="section-kicker">HEALTH SIGNALS</div><h2 id="trend-heading">Your last {dateRange} days</h2></div>
                <div className="period-control" role="group" aria-label="Chart period">
                  {([7, 30] as const).map((period) => (
                    <button className={dateRange === period ? "period-button selected" : "period-button"} key={period} onClick={() => setDateRange(period)} type="button" aria-pressed={dateRange === period}>{period}D</button>
                  ))}
                </div>
              </div>
              <div className="metric-tabs" role="group" aria-label="Trend metric">
                {metricOptions.map((metric) => (
                  <button className={selectedMetric === metric ? "metric-tab selected" : "metric-tab"} key={metric} onClick={() => setSelectedMetric(metric)} type="button" aria-pressed={selectedMetric === metric}>
                    {metricDisplay[metric].label}
                  </button>
                ))}
              </div>
              <div className="chart-wrap" role={chartData.length ? "img" : undefined} aria-label={chartData.length ? `${selectedSeries.label} over ${dateRange} days` : undefined} aria-describedby={chartData.length ? "trend-chart-summary" : undefined}>
                {chartData.length > 0 ? (
                  <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={chartData} margin={{ top: 8, right: 8, left: -22, bottom: 0 }}>
                      <defs><linearGradient id="trendFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={selectedSeries.color} stopOpacity={0.2} /><stop offset="100%" stopColor={selectedSeries.color} stopOpacity={0.015} /></linearGradient></defs>
                      <CartesianGrid vertical={false} stroke="#e9eeea" strokeDasharray="3 5" />
                      <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{ fill: "#7c8982", fontSize: 12 }} minTickGap={24} />
                      <YAxis axisLine={false} tickLine={false} tick={{ fill: "#7c8982", fontSize: 12 }} width={42} domain={chartDomain} />
                      {selectedMetricData?.usualRange28 && (
                        <ReferenceArea
                          y1={selectedMetricData.usualRange28[0]}
                          y2={selectedMetricData.usualRange28[1]}
                          fill={selectedSeries.color}
                          fillOpacity={0.1}
                          strokeOpacity={0}
                        />
                      )}
                      {personalMedian !== null && <ReferenceLine y={personalMedian} stroke={selectedSeries.color} strokeDasharray="4 4" strokeOpacity={0.8} />}
                      <Tooltip contentStyle={{ border: "1px solid #e5ebe6", borderRadius: 8, boxShadow: "0 8px 24px #1b362610" }} formatter={(value) => [`${Number(value).toFixed(1)} ${selectedMetricData?.unit ?? ""}`, selectedSeries.label]} />
                      <Area type="monotone" dataKey="value" stroke={selectedSeries.color} strokeWidth={2.5} fill="url(#trendFill)" activeDot={{ r: 4, strokeWidth: 2, fill: "#fff" }} dot={false} />
                    </AreaChart>
                  </ResponsiveContainer>
                ) : (
                  <div className="chart-empty" role="status">{isLoading ? "Loading readings…" : selectedMetricData?.unavailableReason ?? "No readings available for this metric."}</div>
                )}
              </div>
              <p className="chart-text-summary" id="trend-chart-summary">
                {chartData.length > 0 ? `${chartData.length} dated readings. Latest: ${formatValue(selectedMetric, chartData[chartData.length - 1].value, selectedMetricData?.unit ?? "")}.${selectedMetricData?.usualRange28 ? ` ${selectedMetricData.rangeLabel}: ${formatValue(selectedMetric, selectedMetricData.usualRange28[0], selectedMetricData.unit)} to ${formatValue(selectedMetric, selectedMetricData.usualRange28[1], selectedMetricData.unit)}.` : " No personal range is available."}${personalMedian !== null && selectedMetricData ? ` Prior 28-day median: ${formatValue(selectedMetric, personalMedian, selectedMetricData.unit)}.` : ""}` : "No chart is shown without dated readings."}
              </p>
              {selectedMetricData && (
                <div className="trend-footnote" aria-label="Chart legend">
                  <span className="legend-key"><span className="legend-dot" style={{ backgroundColor: selectedSeries.color }} />{selectedSeries.label}</span>
                  {selectedMetricData.usualRange28 && <span className="legend-key"><span className="legend-band" style={{ backgroundColor: selectedSeries.color }} />{selectedMetricData.rangeLabel}</span>}
                  {personalMedian !== null && <span className="legend-key"><span className="legend-median" style={{ borderColor: selectedSeries.color }} />Prior 28-day median</span>}
                </div>
              )}
            </section>

            <section className="panel recovery-timeline-panel" id="patterns" aria-labelledby="patterns-heading">
              <div className="panel-header activity-header">
                <div><div className="section-kicker">RECOVERY TIMELINE</div><h2 id="patterns-heading">Last 7 days together</h2></div>
              </div>
              <p className="pattern-intro">Each reading is compared with its own usual range. Missing readings stay blank.</p>
              {timelineDays.length > 0 ? (
                <div className="recovery-table-scroll" role="region" aria-label="Seven-day recovery timeline" tabIndex={0}>
                  <table className="recovery-table">
                    <caption className="chart-text-summary">Daily HRV, sleep score and duration, resting heart rate, Body Battery, and stress with personal-range status.</caption>
                    <thead>
                      <tr>
                        <th scope="col">Metric</th>
                        {timelineDays.map((day) => <th scope="col" key={day}>{formatDate(day)}</th>)}
                      </tr>
                    </thead>
                    <tbody>
                      {timelineMetricOptions.map((metricKey) => {
                        const metric = currentData?.metrics[metricKey];
                        const pointsByDate = new Map((metric?.points ?? []).map((point) => [point.date, point.value]));
                        return (
                          <tr key={metricKey}>
                            <th scope="row"><span>{metricDisplay[metricKey].label}</span><small>{metric?.unit ?? ""}</small></th>
                            {timelineDays.map((day) => {
                              const value = pointsByDate.get(day);
                              const status = value === undefined ? "missing" : getTimelineStatus(metric, value);
                              const shownValue = value === undefined ? "—" : formatTimelineValue(metricKey, value);
                              const description = value === undefined
                                ? `${metricDisplay[metricKey].label} on ${formatDate(day)} unavailable`
                                : `${metricDisplay[metricKey].label} on ${formatDate(day)}: ${shownValue}, ${status === "within" ? "within" : status === "outside" ? "outside" : "no"} usual range`;
                              return <td key={day}><span className={`timeline-value ${status}`} aria-label={description} title={description}>{shownValue}</span></td>;
                            })}
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              ) : (
                <div className="chart-empty" role="status">{isLoading ? "Loading daily readings…" : "No dated readings available for the timeline."}</div>
              )}
              <div className="timeline-legend" aria-label="Timeline legend">
                <span><i className="timeline-key within" />Within usual range</span>
                <span><i className="timeline-key outside" />Outside usual range</span>
                <span><i className="timeline-key missing" />Unavailable</span>
              </div>
            </section>
          </div>

          <section className="baseline-strip" aria-label="How to read personal-range colors">
            <div className="baseline-icon"><HeartPulse size={18} /></div>
            <div className="baseline-copy"><strong>How to read this</strong><span>Red means outside your usual range, not automatically bad; green means within it. HRV uses Garmin&apos;s balanced range, while other ranges use your prior 28 days.</span></div>
            <div className="baseline-coverage"><span className="coverage-dot" />{currentData ? `${availableBaselineCount} of 6 ranges ready` : "Waiting for readings"}</div>
          </section>

          <footer className="page-footer"><span>Health Signals <span className="footer-separator">/</span> Private Garmin data</span><span>Measurements are descriptive, not medical advice</span></footer>
        </div>
      </main>
    </div>
  );
}

function MetricCard({ icon, iconClass, metricKey, metric }: {
  icon: React.ReactNode;
  iconClass: string;
  metricKey: MetricKey;
  metric?: MetricData;
}) {
  const latest = metric?.latest;
  const usualRange = metric?.usualRange28;
  const statusLabel = metric?.garminStatus
    ? `Garmin status: ${metric.garminStatus}`
    : metric?.status === "within_usual"
    ? "Within your usual range"
    : metric?.status === "below_usual"
      ? "Below your usual range"
      : metric?.status === "above_usual"
        ? "Above your usual range"
        : metric?.status === "insufficient_history"
          ? "Building your baseline"
          : metric?.unavailableReason ?? "Unavailable";

  return (
    <article className="metric-card">
      <div className="metric-card-top"><span className={`metric-icon ${iconClass}`}>{icon}</span><span className="metric-label">{metric?.label ?? metricDisplay[metricKey].label}</span></div>
      <div className="metric-value-row"><strong>{latest ? formatValue(metricKey, latest.value, metric?.unit ?? "") : "Unavailable"}</strong></div>
      <div className="metric-detail">{latest ? `Latest · ${formatDate(latest.date)}` : metric?.unavailableReason ?? "Waiting for Garmin data"}</div>
      <div className={`metric-status ${metric?.status ?? "unavailable"}`}>{statusLabel}</div>
      <div className="metric-baseline">{usualRange && metric ? `${metric.rangeLabel}: ${formatValue(metricKey, usualRange[0], metric.unit)}–${formatValue(metricKey, usualRange[1], metric.unit)}` : metric?.status === "insufficient_history" ? "Need more prior readings" : "Personal range unavailable"}</div>
    </article>
  );
}